WITH cleaned AS (SELECT *, CAST(cost AS INT) AS cost_int FROM shipments WHERE order_id IS NOT NULL) SELECT *, AVG(cost) OVER (ORDER BY shipped_date, id ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS cost_avg_6_prior, FIRST_VALUE(cost_int) IGNORE NULLS OVER (ORDER BY cost, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_cost_int, COUNT(cost_int) OVER (PARTITION BY order_id, carrier) AS order_id_count_cost_int FROM cleaned
